global.set('utils', {

    build_connection_name: (clients) => {
        return [...clients]
            .sort((a, b) => a.client_system.localeCompare(b.client_system))
            .map(c => `${c.client_system}:${c.identifier}`)
            .join("_");
    },

    build_label: (client) => {
        const colors = {
            wasos:        "#1f871f",
            rayvn:        "#000000",
            parat_bridge: "#b80d18"
        };
        return {
            id:       client.identifier,
            name:     `[${client.client_system}]: ${client.name}`,
            colorHex: colors[client.client_system] || "#888888"
        };
    },

    build_callsign: (client) => `[${client.client_system}:${client.name}]`
});

return msg;

/*
    Sets the parat_bridge global structure.
    On first run: creates the full skeleton.
    On restart: preserves existing data, refreshes base_urls,
    ensures all sub-properties exist.
    Connections and queue are populated by their own init nodes.
*/

const BASE_URLS = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};

let data = global.get("parat_bridge");

if (!data || typeof data !== "object") {
    data = {
        base_urls:   BASE_URLS,
        connections: {},
        queue: {
            in_flight_connections: [],
            entry_queue: []
        }
    };
} else {
    data.base_urls = BASE_URLS;
    if (!data.connections) data.connections = {};
    if (!data.queue) data.queue = {};
    if (!data.queue.entry_queue) data.queue.entry_queue = [];
    if (!data.queue.in_flight_connections) data.queue.in_flight_connections = [];
}

global.set("parat_bridge", data);

return msg;

const connections = global.get("parat_bridge.connections");

if (!connections) {
    msg.payload = [];
    return msg;
}


msg.payload = Object.values(connections).map(conn => {
    const clients = Object.values(conn.clients);
    return {
        "Klient 1": `${clients[0].client_system} — ${clients[0].name}`,
        "Klient 2": `${clients[1].client_system} — ${clients[1].name}`,
        status:     conn.active ? "🟢 aktiv" : "🔴 inaktiv",
        created:    new Date(conn.time_created).toLocaleString()
    };
});


return msg;

let errorLog = global.get('error_log') || [];

// Vis de siste 10 feilene, nyeste først
const recent = errorLog.slice(-10).reverse();

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type.toUpperCase(),
    source: e.source,
    status: e.statusCode || 'none',
    message: e.message.substring(0, 60)
}));

return msg;

const now = Date.now();
const conn = msg.connection;
const failed = msg.failed_messages || [];
const failedEntry = failed[0] || {};

// Target is the system entry tried to reach - and failed
// Sender is in the oposite system of target
const target = failedEntry.target;

// Technical log entry
const logEntry = [{
    id: "pb-queue-" + now + "-" + Math.random().toString(36).substr(2, 6),
    text: "[parat-bridge] Queue exhausted retries. " +
          failed.length + " message(s) failed. Target: " + (target || "unknown") +
          ". Connection: " + (conn ? conn.label : "unknown"),
    timeCreated: now,
    loggedByFullName: "parat-bridge",
    client: "parat-bridge",
    connection_id: conn ? conn.id : null
}];

let msgLog = { payload: logEntry };

if (target === "rayvn") {
    // Faild send to Rayvn - alert Wasos
    const wasosMessage = [{
        content: "[parat-bridge] ⚠️ Melding ikke levert til Rayvn. Forsøker å gjenopprette.",
        callsign: "[parat-bridge]",
        createdAt: new Date(now).toISOString(),
        isLocation: false,
        replyMessageId: null,
        files: []
    }];
    let msgWasos = { payload: wasosMessage, connection: conn };
    return [msgWasos, null, msgLog];

} else if (target === "wasos") {
    // Faild send to Wasos - alert Rayvn
    const rayvnMessage = [{
        text: "[parat-bridge] ⚠️ Melding ikke levert til WaSOS. Forsøker å gjenopprette.",
        keyEvent: false,
        releasedInfo: false,
        labels: []
    }];
    let msgRayvn = { payload: rayvnMessage, connection: conn };
    return [null, msgRayvn, msgLog];

} else {
    // Unknown target
    node.warn("Unknown target for failed message: " + target);
    return [null, null, msgLog];
}

/*
    Restores entry_queue from /data/bridge-files/queue.json.
    in_flight_connections is runtime-only — always starts empty.
*/

const QUEUE_FILE = '/data/bridge-files/queue.json';

if (fs.existsSync(QUEUE_FILE)) {
    const saved = JSON.parse(fs.readFileSync(QUEUE_FILE, 'utf8'));
    global.set("parat_bridge.queue.entry_queue", saved.entry_queue || []);
    node.log("Restored " + (saved.entry_queue || []).length + " queue entries from disk");
} else {
    node.log("No queue file — starting with empty queue");
}

return msg;

/*
    Reads connection files from /data/bridge-files/connections/.
    Each connection is a separate JSON file.
    On first run (no files): keeps the empty {} from parat_bridge init.
*/

const CONNECTIONS_DIR = '/data/bridge-files/connections/';

const files = fs.readdirSync(CONNECTIONS_DIR).filter(f => f.endsWith('.json'));

if (files.length > 0) {
    const connections = {};
    files.forEach(f => {
        const data = JSON.parse(fs.readFileSync(CONNECTIONS_DIR + f, 'utf8'));
        connections[data.name] = data;
    });
    global.set("parat_bridge.connections", connections);
    node.log("Restored " + files.length + " connection(s) from disk");
} else {
    node.log("No connection files — starting with empty connections");
}

return msg;

/*
    Overrides global.set and global.get for automatic disk persistence.
    Runs before all other nodes in the startup sequence.

    parat_bridge.connections.<name>.*  →  memory + persist to /data/bridge-files/connections/<name>.json
    parat_bridge.queue.*              →  memory + persist to /data/bridge-files/queue.json
    files.<filename>                  →  /data/bridge-files/files/<filename> only (no memory)
    everything else                   →  unchanged
*/

const writeAtomic = writeFileAtomic.sync;
const originalSet = global.set.bind(global);
const originalGet = global.get.bind(global);

const BASE_DIR       = '/data/bridge-files/';
const QUEUE_FILE     = BASE_DIR + 'queue.json';
const CONNECTIONS_DIR = BASE_DIR + 'connections/';
const FILES_DIR      = BASE_DIR + 'files/';

const sanitize = (name) => name.replace(/:/g, '_');

[CONNECTIONS_DIR, FILES_DIR].forEach(dir => {
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
});

// --- set override ---

global.set = (path, value, ...args) => {
    if (typeof path !== 'string') return originalSet(path, value, ...args);

    const parts = path.split('.');

    // redirect files to disk
    if (parts[0] === 'files' && parts.length > 1) {
        fs.writeFileSync(FILES_DIR + sanitize(parts.slice(1).join('.')), value);
        return;
    }

    originalSet(path, value, ...args);


    // persist connections
    if (parts[0] === 'parat_bridge' && parts[1] === 'connections' && parts[2]) {
        const connection = originalGet(`parat_bridge.connections.${parts[2]}`);
        if (connection) {
            writeAtomic(CONNECTIONS_DIR + sanitize(parts[2]) + '.json', JSON.stringify(connection));
        }
    }

    // persist queue
    if (parts[0] === 'parat_bridge' && parts[1] === 'queue') {
        writeAtomic(QUEUE_FILE, JSON.stringify({
            entry_queue: originalGet('parat_bridge.queue.entry_queue') || []
        }));
    }
};

// --- get override ---

global.get = (path, ...args) => {
    if (typeof path === 'string') {
        const parts = path.split('.');
        if (parts[0] === 'files' && parts.length > 1) {
            const filePath = FILES_DIR + sanitize(parts.slice(1).join('.'));
            if (fs.existsSync(filePath)) return fs.readFileSync(filePath);
            return null;
        }
    }
    return originalGet(path, ...args);
};

return msg;
